def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Count prime factors with multiplicity (e.g., 8 = 2*2*2 -> count=3)
    def get_prime_factor_count(n, primes=None):
        """Returns the number of times a is multiplied by its smallest prime factor."""
        if n == 1:
            return 0

        # Find all divisors and check primality on the fly to avoid precomputing for small range
        count = 0
        d = 2
        temp = n
        while d * d <= temp:
            while temp % d == 0:
                if is_prime(d):
                    count += 1
                else:
                    # If a divisor isn't prime, it must be composite; 
                    # we can stop because any further factorization will still yield primes.
                    break
                temp //= d
            d += 1

        # Handle remaining n > 1 (it's guaranteed to be prime)
        if temp > 1:
            count += 1

        return count

    # For numbers < 100, we can also directly check all combinations of three primes.
    # But the factor-count method is general and efficient enough here.

    return get_prime_factor_count(a) == 3


# Example usage:
print(is_multiply_prime(30))   # True (2 * 3 * 5)

